CREATE TRIGGER update_papeis_updated_at
AFTER UPDATE ON papeis
FOR EACH ROW
BEGIN
  UPDATE papeis SET updated_at = datetime('now') WHERE id = OLD.id;
END;
CREATE TRIGGER update_credenciais_updated_at
AFTER UPDATE ON credenciais
FOR EACH ROW
BEGIN
  UPDATE credenciais SET updated_at = datetime('now') WHERE id = OLD.id;
END;
CREATE TRIGGER update_qt_timestamp 
AFTER UPDATE ON "qualificacoes_tipos_old"
FOR EACH ROW
BEGIN
  UPDATE "qualificacoes_tipos_old" SET updated_at = datetime('now') WHERE id = NEW.id;
END;
CREATE TRIGGER trg_funcionarios_prevent_hard_delete
BEFORE DELETE ON "funcionarios_backup"
FOR EACH ROW
BEGIN
  SELECT RAISE(ABORT, 'DELETE físico proibido. Use soft delete (UPDATE deleted_at)');
END;
CREATE TRIGGER trg_audit_funcionarios_update
BEFORE UPDATE ON "funcionarios_backup"
FOR EACH ROW
WHEN NEW.deleted_at IS NULL -- apenas updates não deletando
BEGIN
    tabela, registro_id, acao, origem, created_at
  ) VALUES (
    'funcionarios', OLD.id, 'UPDATE', 'trigger', datetime('now')
  );
END;
CREATE TRIGGER trg_audit_funcionarios_soft_delete_after_update
AFTER UPDATE ON "funcionarios_backup"
FOR EACH ROW
WHEN NEW.deleted_at IS NOT NULL AND OLD.deleted_at IS NULL
BEGIN
  VALUES ('funcionarios', NEW.id, 'SOFT_DELETE', 'trigger', datetime('now'));
END;
CREATE TRIGGER trg_qualificacoes_tipos_prevent_hard_delete BEFORE DELETE ON "qualificacoes_tipos_old" FOR EACH ROW BEGIN SELECT RAISE(ABORT,'DELETE físico proibido em qualificacoes_tipos. Use soft delete'); END;
CREATE TRIGGER update_historico_timestamp
AFTER UPDATE ON qualificacoes_historico
FOR EACH ROW
BEGIN
  UPDATE qualificacoes_historico 
  SET updated_at = CURRENT_TIMESTAMP 
  WHERE id = NEW.id;
END;
CREATE TRIGGER trg_tipo_update_recalcular_historico
AFTER UPDATE ON qualificacoes_tipos
WHEN NEW.validade != OLD.validade 
  OR NEW.vencimento_fim_mes != OLD.vencimento_fim_mes
BEGIN
  -- Atualizar data_vencimento de todos os registros deste tipo
  UPDATE qualificacoes_historico
  SET 
    data_vencimento = CASE
      -- Se vencimento_fim_mes = TRUE, último dia do mês
      WHEN NEW.vencimento_fim_mes = 1 THEN 
        DATE(data_conclusao, '+' || NEW.validade || ' months', 'start of month', '+1 month', '-1 day')
      -- Se FALSE, data exata
      ELSE 
        DATE(data_conclusao, '+' || NEW.validade || ' months')
    END,
    updated_at = CURRENT_TIMESTAMP
  WHERE qualificacao_id = NEW.id
    AND deleted_at IS NULL
    AND renovada != 1;
END;
CREATE TRIGGER trg_qualificacoes_tipos_update
AFTER UPDATE ON qualificacoes_tipos
FOR EACH ROW
WHEN OLD.deleted_at IS NULL  -- Apenas updates em registros ativos
BEGIN
    tabela, 
    registro_id, 
    acao, 
    dados_anteriores, 
    dados_novos
  )
  VALUES (
    'qualificacoes_tipos', 
    NEW.id, 
    'UPDATE',
    json_object(
      'codigo', OLD.codigo, 
      'nome', OLD.nome, 
      'validade', OLD.validade,
      'vencimento_fim_mes', OLD.vencimento_fim_mes,
      'categoria', OLD.categoria,
      'ativo', OLD.ativo
    ),
    json_object(
      'codigo', NEW.codigo, 
      'nome', NEW.nome, 
      'validade', NEW.validade,
      'vencimento_fim_mes', NEW.vencimento_fim_mes,
      'categoria', NEW.categoria,
      'ativo', NEW.ativo
    )
  );
END;
CREATE TRIGGER trg_tipo_update_auditoria AFTER UPDATE ON qualificacoes_tipos WHEN NEW.validade != OLD.validade OR NEW.vencimento_fim_mes != OLD.vencimento_fim_mes BEGIN INSERT INTO auditoria_avancada_v2 (tabela, registro_id, acao, dados_anteriores, dados_novos) VALUES ('qualificacoes_tipos', NEW.id, 'UPDATE_TIPO_RECALCULO', json_object('validade', OLD.validade, 'vencimento_fim_mes', OLD.vencimento_fim_mes), json_object('validade', NEW.validade, 'vencimento_fim_mes', NEW.vencimento_fim_mes)); END;
CREATE TRIGGER trigger_modelos_sessao_manobras_updated_at
AFTER UPDATE ON modelos_sessao_manobras
FOR EACH ROW
BEGIN
  UPDATE modelos_sessao_manobras
  SET updated_at = datetime('now')
  WHERE id = NEW.id;
END;
CREATE TRIGGER trg_marcar_renovada_insert
AFTER INSERT ON qualificacoes_historico
FOR EACH ROW
WHEN NEW.deleted_at IS NULL
BEGIN
  UPDATE qualificacoes_historico
  SET renovada = CASE
    WHEN EXISTS (
      SELECT 1
      FROM qualificacoes_historico qh_anterior
      WHERE qh_anterior.funcionario_cpf = NEW.funcionario_cpf
        AND qh_anterior.qualificacao_codigo = NEW.qualificacao_codigo
        AND qh_anterior.deleted_at IS NULL
        AND qh_anterior.id < NEW.id
        AND date(NEW.data_conclusao) < date(qh_anterior.data_vencimento)
    ) THEN 1
    ELSE 0
  END
  WHERE id = NEW.id;
END;
CREATE TRIGGER trg_marcar_renovada_update
AFTER UPDATE OF data_conclusao, data_vencimento, funcionario_cpf, qualificacao_codigo
ON qualificacoes_historico
FOR EACH ROW
WHEN NEW.deleted_at IS NULL
BEGIN
  UPDATE qualificacoes_historico
  SET renovada = CASE
    WHEN EXISTS (
      SELECT 1
      FROM qualificacoes_historico qh_anterior
      WHERE qh_anterior.funcionario_cpf = NEW.funcionario_cpf
        AND qh_anterior.qualificacao_codigo = NEW.qualificacao_codigo
        AND qh_anterior.deleted_at IS NULL
        AND qh_anterior.id < NEW.id
        AND date(NEW.data_conclusao) < date(qh_anterior.data_vencimento)
    ) THEN 1
    ELSE 0
  END
  WHERE id = NEW.id;
END;
